PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?point ?label ?ref ?tsid WHERE {
  ?zone brick:hasPoint ?point .
  ?zone rdfs:label ?zl .
  FILTER (CONTAINS(?zl, "Core"))
  ?point rdfs:label ?label .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?point ref:hasExternalReference ?ref }
} LIMIT 200

